    @Test
    void cartaoAcimaDe12ParcelasEhInvalido() {
        assertThatThrownBy(() -> calcular(pedido(
                List.of(camiseta(1)), "EXPRESSA", null, "CARTAO", 13, "BRONZE", "SUDESTE")))
                .hasMessage("PARCELAMENTO_INVALIDO");
