    @Test
    void formaDePagamentoAusenteEhInvalida() {
        assertThatThrownBy(() -> calcular(pedido(
                List.of(camiseta(1)), "EXPRESSA", null, null, null, "BRONZE", "SUDESTE")))
                .hasMessage("FORMA_PAGAMENTO_INVALIDA");
